package DAY3;

public class For_Loop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//Input any integer and print its multiplication table (from 1 to 10) using a for loop.
		
		int n=8;
		
		for(int i=1;i<=10;i++){
			int N = i*n;
			System.out.println(n + " * " + i + " = " + N);
		}

	}

}
